import {
  Entity,
  PrimaryGeneratedColumn,
  Column,
  CreateDateColumn,
  UpdateDateColumn,
  ManyToOne,
  JoinColumn,
  Index,
} from 'typeorm';
import { OrganizationEntity } from '../../organizations/organization.entity';
import { ContactEntity } from '../../client-management/contact.entity';
import { ConversationEntity } from '../../conversation-management/conversation.entity';
import { PaymentServiceEntity } from './payment-service.entity';

export type PaymentStatus = 'pending' | 'paid' | 'expired' | 'canceled' | 'failed';

/** One Stripe Checkout link generated by the agent for a specific contact. */
@Entity({ name: 'payments', schema: 'payments' })
@Index(['organization_id'])
@Index(['contact_id'])
export class PaymentEntity {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column({ type: 'uuid' })
  organization_id: string;

  @ManyToOne(() => OrganizationEntity, { onDelete: 'CASCADE' })
  @JoinColumn({ name: 'organization_id' })
  organization: OrganizationEntity;

  @Column({ type: 'uuid', nullable: true })
  service_id: string | null;

  @ManyToOne(() => PaymentServiceEntity, { onDelete: 'SET NULL', nullable: true })
  @JoinColumn({ name: 'service_id' })
  service: PaymentServiceEntity | null;

  @Column({ type: 'uuid' })
  contact_id: string;

  @ManyToOne(() => ContactEntity, { onDelete: 'CASCADE' })
  @JoinColumn({ name: 'contact_id' })
  contact: ContactEntity;

  @Column({ type: 'uuid', nullable: true })
  conversation_id: string | null;

  @ManyToOne(() => ConversationEntity, { onDelete: 'SET NULL', nullable: true })
  @JoinColumn({ name: 'conversation_id' })
  conversation: ConversationEntity | null;

  /** Set when this payment gates an appointment — confirmed once Stripe pays. */
  @Column({ type: 'uuid', nullable: true })
  appointment_id: string | null;

  /** Cents, snapshotted from the service at creation time (price changes don't retro-affect it). */
  @Column({ type: 'integer' })
  amount: number;

  @Column({ length: 10 })
  currency: string;

  @Column({ type: 'varchar', length: 20, default: 'pending' })
  status: PaymentStatus;

  @Column({ type: 'varchar', length: 255, nullable: true, unique: true })
  stripe_checkout_session_id: string | null;

  @Column({ type: 'varchar', length: 255, nullable: true })
  stripe_payment_intent_id: string | null;

  @Column({ type: 'text', nullable: true })
  checkout_url: string | null;

  @Column({ type: 'jsonb', default: {} })
  metadata: Record<string, unknown>;

  @Column({ type: 'timestamptz', nullable: true })
  paid_at: Date | null;

  @CreateDateColumn({ type: 'timestamptz' })
  created_at: Date;

  @UpdateDateColumn({ type: 'timestamptz' })
  updated_at: Date;
}
